package io.github.diodeme.ji.testkit;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/** Runs every fixture declared by the pinned Pi fixture manifest. */
public final class FixtureSuiteRunner {
    private static final ObjectMapper MAPPER = new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);

    private FixtureSuiteRunner() {}

    public static void main(String[] args) throws IOException {
        if (args.length != 2) {
            System.err.println("usage: FixtureSuiteRunner <fixture-directory> <output>");
            System.exit(2);
        }
        Path fixtureDirectory = Path.of(args[0]);
        var manifest = MAPPER.readTree(fixtureDirectory.resolve("manifest.json").toFile());
        ObjectNode results = MAPPER.createObjectNode();
        for (var fixture : manifest.path("fixtures")) {
            String domain = fixture.path("domain").asText();
            if (results.has(domain)) throw new IllegalArgumentException("duplicate Pi fixture domain: " + domain);
            results.set(domain, FixtureRunner.normalize(fixtureDirectory.resolve(fixture.path("path").asText())));
        }
        if (results.size() != 5) throw new IllegalArgumentException("exactly five Pi fixture domains are required");
        Path output = Path.of(args[1]);
        Files.createDirectories(output.toAbsolutePath().getParent());
        MAPPER.writeValue(output.toFile(), results);
    }
}
